<span class="line"><span class="__shiki_1itgoe">    private</span><span class="__shiki_1itgoe"> final</span><span class="__shiki_140thh"> LoadingCache&lt;</span><span class="__shiki_1itgoe">String</span><span class="__shiki_140thh">, </span><span class="__shiki_1itgoe">Product</span><span class="__shiki_140thh">&gt; productCache </span><span class="__shiki_1itgoe">=</span><span class="__shiki_140thh"> </span></span>
